def check_triple(x, y, z):
    return x**3 + y**3 + z**3 - x**2 * y**2 * z**2 == 0

solutions = []
max_z = 15

# Iterate through z
for z in range(1, max_z + 1):
    # Iterate through y, ensuring x <= y <= z
    for y in range(1, z + 1):
        # Iterate through x, ensuring x <= y
        for x in range(1, y + 1):
            if check_triple(x, y, z):
                solutions.append((x, y, z))

print("Solutions found:")
for sol in solutions:
    print(sol)

print(f"\nTotal solutions found up to z={max_z}: {len(solutions)}")

